mapper.select:
select * from ( select a.*, rownum rnum from ( select s.stock_id, li.lot_in_id, p.product_name, p.status as product_type, w.warehouse_name, w.warehouse_id, li.expiration_date, s.quantity as quantity, trunc(li.expiration_date) - trunc(sysdate) as days_left from stock s join lot_in li on s.lot_in_id = li.lot_in_id join inbound_detail id on li.inbound_detail_id = id.inbound_detail_id join product p on id.product_id = p.product_id join warehouse w on li.warehouse_id = w.warehouse_id
order by li.expiration_date asc ) a )
where rnum >= #{startRow} and rnum <= #{endRow}
